using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using EnterpriseDocumentIntelligence.BuildingBlocks.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
public sealed record CreateDocumentRequest(string Name,string ContentType,long SizeBytes,string BlobUri,string Sha256);
public sealed record DocumentResponse(Guid Id,Guid TenantId,string Name,string ContentType,long SizeBytes,string Status,Guid CurrentVersionId);
public sealed class DocumentApp(DocumentDbContext db,ICurrentUser user,ILogger<DocumentApp> log){public async Task<DocumentResponse> CreateAsync(CreateDocumentRequest r,CancellationToken ct){var cmd=new DocumentCreateCommand(user.TenantId,r.Name,r.ContentType,r.SizeBytes,r.BlobUri,r.Sha256);var(d,v)=DocumentRules.Create(cmd);db.Documents.Add(d);await db.SaveChangesAsync(ct);log.LogInformation("Created document {DocumentId} Tenant={TenantId}",d.Id,d.TenantId);return Map(d);}public async Task<DocumentResponse?> GetAsync(Guid id,CancellationToken ct){var d=await db.Documents.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.TenantId==user.TenantId,ct);return d is null?null:Map(d);}public async Task<IReadOnlyList<DocumentResponse>> ListAsync(CancellationToken ct)=>await db.Documents.AsNoTracking().Where(x=>x.TenantId==user.TenantId).OrderByDescending(x=>x.CreatedAt).Select(x=>new DocumentResponse(x.Id,x.TenantId,x.Name,x.ContentType,x.SizeBytes,x.Status,x.CurrentVersionId)).Take(100).ToListAsync(ct);static DocumentResponse Map(Document d)=>new(d.Id,d.TenantId,d.Name,d.ContentType,d.SizeBytes,d.Status,d.CurrentVersionId);}
[ApiController,Route("api/v1/documents"),Authorize]public sealed class DocumentsController(DocumentApp app):ControllerBase{[HttpPost][Authorize(Roles=Roles.Contributor+","+Roles.Administrator)]public async Task<ActionResult<DocumentResponse>>Create(CreateDocumentRequest r,CancellationToken ct)=>Ok(await app.CreateAsync(r,ct));[HttpGet][Authorize(Roles=Roles.Reader+","+Roles.Contributor+","+Roles.Administrator)]public async Task<ActionResult<IReadOnlyList<DocumentResponse>>>List(CancellationToken ct)=>Ok(await app.ListAsync(ct));[HttpGet("{id:guid}")][Authorize(Roles=Roles.Reader+","+Roles.Contributor+","+Roles.Administrator)]public async Task<ActionResult<DocumentResponse>>Get(Guid id,CancellationToken ct){var x=await app.GetAsync(id,ct);return x is null?NotFound():Ok(x);}}